import numpy as np,json,sys
from scipy.spatial.transform import Rotation
from rcb_client import Robot
from PIL import Image
r=Robot();s=r.spec();lim=np.array(s['qpos']['range']);axes=np.array(s['proprio']['axis']);pos=np.array(s['proprio']['position_m'])
def act(q):return np.clip(2*(np.array(q)-lim[:,0])/(lim[:,1]-lim[:,0])-1,-1,1)
def rot(a,t):return Rotation.from_rotvec(a*t).as_matrix()
def fk(q,point,chain):
 p=np.array(point,float)
 for i in reversed(chain):p=pos[i]+rot(axes[i],q[i])@(p-pos[i])
 return p
cam=s['cameras']['room_camera']['pose'];C=np.array(cam['position_m']);F=np.array(cam['forward']);U=np.array(cam['up']);R=np.array(cam['right']);f=128/np.tan(np.pi/8)
def project(p):
 d=np.array(p)-C;return np.array([128+f*np.dot(d,R)/np.dot(d,F),128-f*np.dot(d,U)/np.dot(d,F)])
def unproject(u,v,z):
 ray=F+(u-128)/f*R-(v-128)/f*U;return C+ray*((z-C[2])/ray[2])
def save(o):
 for k,v in o.get('images',{}).items():Image.fromarray(v).save('/app/output/'+k+'.png')
 open('/app/output/current.json','w').write(json.dumps({k:v for k,v in o.items() if k not in ['images','depth']}))
 print({k:v for k,v in o.items() if k not in ['images','depth']})
def move(q,n=1):
 with open('/app/output/trajectory.jsonl','a') as h:h.write(json.dumps({'q':np.asarray(q).tolist(),'n':n})+'\n')
 o=r.step('qpos',[act(q).tolist()]*n,images=['room_camera']);save(o);return o
if __name__=='__main__':
 o=r.observe();save(o)
 q=np.array(o['proprio']['joint_pos']);print('feet',fk(q,[-.061,.203,-1.065],[0,1,2,3,4]));print('hand',fk(q,[.329,.214,.097],[10,11,12,13,14]))
 for z in [.8,.9,1.,1.1]:print(z,unproject(117,140,z),unproject(141,152,z))
